  <title>Support Contact</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --panel: rgba(255, 255, 255, 0.92);
      --panel-border: rgba(148, 163, 184, 0.18);
      --text: #0f172a;
      --muted: #475569;
      --muted-soft: #64748b;
      --primary: #2563eb;
      --primary-strong: #1d4ed8;
      --danger: #dc2626;
      --shadow: 0 24px 70px rgba(15, 23, 42, 0.12);
      --radius: 24px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top left, rgba(37, 99, 235, 0.14), transparent 32%),
        radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.16), transparent 28%),
        var(--bg);
      color: var(--text);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 32px 16px;
    }

    .page-shell {
      width: min(100%, 1080px);
      display: grid;
      grid-template-columns: minmax(0, 1.05fr) minmax(320px, 0.95fr);
      gap: 28px;
      align-items: stretch;
    }

    .hero-panel,
    .form-panel {
      background: var(--panel);
      border: 1px solid var(--panel-border);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      backdrop-filter: blur(14px);
    }

    .hero-panel {
      padding: 40px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: 32px;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      padding: 8px 14px;
      border-radius: 999px;
      background: rgba(37, 99, 235, 0.1);
      color: var(--primary-strong);
      font-size: 0.9rem;
      font-weight: 700;
      letter-spacing: 0.02em;
    }

    h1 {
      margin: 18px 0 14px;
      font-size: clamp(2rem, 3.5vw, 3.3rem);
      line-height: 1.05;
      letter-spacing: -0.03em;
    }

    .hero-copy {
      margin: 0;
      font-size: 1rem;
      line-height: 1.7;
      color: var(--muted);
      max-width: 34rem;
    }

    .feature-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 14px;
    }

    .feature-card {
      padding: 18px;
      border-radius: 18px;
      background: rgba(248, 250, 252, 0.86);
      border: 1px solid rgba(148, 163, 184, 0.16);
    }

    .feature-card strong {
      display: block;
      margin-bottom: 8px;
      font-size: 0.95rem;
    }

    .feature-card span {
      color: var(--muted-soft);
      font-size: 0.94rem;
      line-height: 1.55;
    }

    .form-panel {
      padding: 32px;
    }

    .form-panel h2 {
      margin: 0 0 10px;
      font-size: 1.5rem;
      letter-spacing: -0.02em;
    }

    .form-panel > p {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 20px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 700;
      font-size: 0.96rem;
    }

    input {
      width: 100%;
      border: 1px solid rgba(148, 163, 184, 0.35);
      border-radius: 14px;
      padding: 14px 16px;
      font: inherit;
      color: var(--text);
      background: #fff;
      transition: border-color 140ms ease, box-shadow 140ms ease, transform 140ms ease;
    }

    input::placeholder {
      color: #94a3b8;
    }

    input:focus {
      outline: none;
      border-color: var(--primary);
      box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.15);
      transform: translateY(-1px);
    }

    .helper-text,
    .error-text {
      min-height: 1.25rem;
      font-size: 0.92rem;
      line-height: 1.4;
    }

    .helper-text {
      color: var(--muted-soft);
    }

    .error-text {
      color: var(--danger);
    }

    .submit-button {
      border: 0;
      border-radius: 14px;
      padding: 15px 18px;
      font: inherit;
      font-weight: 700;
      color: #fff;
      background: linear-gradient(135deg, var(--primary), var(--primary-strong));
      cursor: pointer;
      box-shadow: 0 14px 30px rgba(37, 99, 235, 0.28);
      transition: transform 140ms ease, box-shadow 140ms ease, filter 140ms ease;
    }

    .submit-button:hover,
    .submit-button:focus-visible {
      transform: translateY(-1px);
      box-shadow: 0 18px 34px rgba(37, 99, 235, 0.32);
      filter: brightness(1.02);
    }

    .submit-button:focus-visible {
      outline: 3px solid rgba(37, 99, 235, 0.2);
      outline-offset: 3px;
    }

    .success-message {
      margin: 0;
      padding: 14px 16px;
      border-radius: 14px;
      background: rgba(22, 163, 74, 0.1);
      color: #166534;
      font-weight: 600;
    }

    @media (max-width: 880px) {
      .page-shell {
        grid-template-columns: 1fr;
      }

      .feature-grid {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 560px) {
      .hero-panel,
      .form-panel {
        padding: 24px;
        border-radius: 20px;
      }

      body {
        padding: 16px;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>
  <script>
    const root = document.getElementById("app");

    function createElement(tag, options = {}) {
      const element = document.createElement(tag);

      if (options.className) {
        element.className = options.className;
      }

      if (options.text) {
        element.textContent = options.text;
      }

      if (options.html) {
        element.innerHTML = options.html;
      }

      if (options.attributes) {
        Object.entries(options.attributes).forEach(([key, value]) => {
          if (value !== undefined && value !== null) {
            element.setAttribute(key, value);
          }
        });
      }

      return element;
    }

    function FeatureCard(title, copy) {
      const card = createElement("div", { className: "feature-card" });
      card.append(
        createElement("strong", { text: title }),
        createElement("span", { text: copy })
      );
      return card;
    }

    function FormField(config) {
      const field = createElement("div", { className: "form-field" });
      const label = createElement("label", {
        text: config.label,
        attributes: { for: config.id }
      });
      const input = createElement("input", {
        attributes: {
          id: config.id,
          name: config.name,
          type: config.type,
          placeholder: config.placeholder,
          required: config.required ? "required" : null,
          "aria-describedby": config.describedBy,
          autocomplete: config.autocomplete
        }
      });

      const helper = createElement("p", {
        className: "helper-text",
        text: config.helperText || "",
        attributes: { id: config.helperId || "" }
      });

      if (!config.helperText) {
        helper.setAttribute("aria-hidden", "true");
      }

      const error = createElement("p", {
        className: "error-text",
        attributes: {
          id: config.errorId,
          role: "alert",
          "aria-live": "polite"
        }
      });

      input.addEventListener("input", () => {
        if (config.onInput) {
          config.onInput(input, error);
        }
      });

      field.append(label, input, helper, error);
      return { field, input, error };
    }

    function SupportForm() {
      const panel = createElement("section", { className: "form-panel" });
      panel.append(
        createElement("h2", { text: "Contact support" }),
        createElement("p", {
          text: "Tell us what you need and our team will reach out with the right next step."
        })
      );

      const form = createElement("form", {
        attributes: { novalidate: "novalidate" }
      });
      const successMessage = createElement("p", {
        className: "success-message",
        text: "Thanks - your support request has been sent.",
        attributes: { hidden: "hidden" }
      });

      const fields = {};

      fields.fullName = FormField({
        id: "fullName",
        name: "fullName",
        label: "Full name",
        type: "text",
        placeholder: "Jordan Lee",
        required: true,
        autocomplete: "name",
        describedBy: "fullName-error",
        errorId: "fullName-error",
        onInput(input, error) {
          if (input.value.trim()) {
            error.textContent = "";
          }
        }
      });

      fields.email = FormField({
        id: "email",
        name: "email",
        label: "Email address",
        type: "email",
        placeholder: "jordan@company.com",
        required: true,
        autocomplete: "email",
        describedBy: "email-error",
        errorId: "email-error",
        onInput(input, error) {
          if (/\S+@\S+\.\S+/.test(input.value.trim())) {
            error.textContent = "";
          }
        }
      });

      fields.phone = FormField({
        id: "phone",
        name: "phone",
        label: "Phone number",
        type: "tel",
        placeholder: "(555) 123-4567",
        autocomplete: "tel",
        describedBy: "phone-helper phone-error",
        helperText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567.",
        helperId: "phone-helper",
        errorId: "phone-error",
        onInput(input, error) {
          if (!input.value.trim() || /^[+]?[\d\s().-]{7,}$/.test(input.value.trim())) {
            error.textContent = "";
          }
        }
      });

      Object.values(fields).forEach(({ field }) => form.appendChild(field));

      const submitButton = createElement("button", {
        className: "submit-button",
        text: "Submit request",
        attributes: { type: "submit" }
      });

      form.append(submitButton, successMessage);

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        successMessage.hidden = true;

        const fullName = fields.fullName.input.value.trim();
        const email = fields.email.input.value.trim();
        const phone = fields.phone.input.value.trim();

        let hasErrors = false;

        if (!fullName) {
          fields.fullName.error.textContent = "Please enter your full name.";
          hasErrors = true;
        } else {
          fields.fullName.error.textContent = "";
        }

        if (!email) {
          fields.email.error.textContent = "Please enter your email address.";
          hasErrors = true;
        } else if (!/\S+@\S+\.\S+/.test(email)) {
          fields.email.error.textContent = "Please enter a valid email address.";
          hasErrors = true;
        } else {
          fields.email.error.textContent = "";
        }

        if (phone && !/^[+]?[\d\s().-]{7,}$/.test(phone)) {
          fields.phone.error.textContent = "Please use the phone number format shown below.";
          hasErrors = true;
        } else {
          fields.phone.error.textContent = "";
        }

        if (hasErrors) {
          return;
        }

        form.reset();
        successMessage.hidden = false;
      });

      panel.appendChild(form);
      return panel;
    }

    function HeroPanel() {
      const panel = createElement("section", { className: "hero-panel" });
      const header = createElement("div");
      header.append(
        createElement("span", { className: "eyebrow", text: "Support page" }),
        createElement("h1", { text: "Fast help for product, billing, and account questions." }),
        createElement("p", {
          className: "hero-copy",
          text: "Reach the support team through a streamlined contact form designed to feel clear, calm, and trustworthy across devices."
        })
      );

      const featureGrid = createElement("div", { className: "feature-grid" });
      featureGrid.append(
        FeatureCard("Quick routing", "Your request lands with the team best equipped to help."),
        FeatureCard("Clear follow-up", "We use your contact details to respond with updates and next steps."),
        FeatureCard("Accessible design", "Readable spacing, strong contrast, and keyboard-friendly controls.")
      );

      panel.append(header, featureGrid);
      return panel;
    }

    function App() {
      const shell = createElement("main", { className: "page-shell" });
      shell.append(HeroPanel(), SupportForm());
      return shell;
    }

    root.appendChild(App());
  </script>
</body>
</html>
